import{z as i,x as s,o as A,c as d,q as n,j as B,D as e,d as t,s as o,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"量化监管演进","description":"","frontmatter":{"title":"量化监管演进","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-quant-regulation-history.md","filePath":"quant/cn-quant-regulation-history.md","lastUpdated":1791413859000}'),p={name:"quant/cn-quant-regulation-history.md"};function u(h,E,m,c,f,D){const r=s("Mermaid");return A(),d("div",null,[E[2]||(E[2]=n('<h1 id="量化监管演进" tabindex="-1">量化监管演进 <a class="header-anchor" href="#量化监管演进" aria-label="Permalink to &quot;量化监管演进&quot;">​</a></h1><div class="epigraph"><p>A 股对程序化与量化的约束是分阶段叠加上去的：从异常交易与申报速率，到报告、高频认定、差异化收费与协会自律。回测必须按公告切换可行集，不能用今日细则惩罚十年前的报单。</p><footer>—— 证监会《证券市场程序化交易管理规定（试行）》（2024）；沪深北《程序化交易管理实施细则》（2025）；对照 2015 年前后交易所异常交易与股指期货监管措施</footer></div><p><a href="/quant/cn-fees-stamp-duty">上一课</a>把价目表时间化。主干<a href="/quant/cn-program-trading-rules">程序化规定</a>、<a href="/quant/cn-hft-threshold">高频认定</a>、<a href="/quant/cn-amac-program-trading">中基协</a>、<a href="/quant/cn-colocation-rectify">托管整改</a> 已写现行文本。本课的缺口是<strong>演进</strong>：2015 股灾后的限仓与平今、2018–19 异常交易监控强化、2023 报告通知、2024 管理规定、2025 实施细则。后课情绪指标用两融与换手，它们同样被监管窗口改写。不把本课写成如何把报单拆到阈值以下。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「中国量化」在 2010 年与 2025 年不是同一合法动作集。2015 年股指期货手续费、保证金、开仓限制使中性产品的对冲腿突然变贵或不可用。其后股票侧对频繁报撤、拉抬打压的监控指标逐步明确。2024 年《管理规定》把先报告后交易升到部门规章；2025 年细则把四类异常与高频写成可执行条文。问题是实验登记必须包含 <code>reg_regime_id</code>：同一策略代码在不同制度下的换手与报撤要分开评价。<span class="marginnote">「制度前视」就是拿今天的交规去裁判十年前的司机。初学者容易以为「规则一直如此」，实际上 2015 年前后一只市场中性产品的对冲成本与可做空工具和 2025 年完全是两个世界；用今天的细则去惩罚 2016 年的报单，得到的「违规损失」在当年根本不存在。</span>用 2025 年细则回测 2016 年，是制度前视。</p><p>公平接入：托管与行情不得为程序化提供特殊便利。境外「付费买更短线」的容量故事，在现行规则下不能当 A 股股票的默认假设，见<a href="/quant/colocation-microwave">托管与微波</a> 的 A 股对照。</p><h3 id="监管是拥挤与容量的状态变量" tabindex="-1">监管是拥挤与容量的状态变量 <a class="header-anchor" href="#监管是拥挤与容量的状态变量" aria-label="Permalink to &quot;监管是拥挤与容量的状态变量&quot;">​</a></h3><p>收紧报撤与融券，使高频做市与个股中性容量下降，指数增强相对受益或受害取决于工具替代。放松则反向。把监管当外生冲击做事件研究合法；把「如何刚好低于阈值」当优化目标，越界成本由规则明确禁止的行为组成，本课不讨论。</p><p><span class="marginnote">北向交易按内外资一致纳入程序化报告与监控。把北向当「另一套监管」与公开规则不符。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>制度日历：重大公告日、施行日、过渡期。回测引擎读取日历以切换：期货费率与限仓、股票异常阈值（若历史公开）、是否需要报告状态、融券管道。<span class="marginnote">可以把它想象成给回测装一排开关面板：每跨过一个公告日，引擎就拨一组开关——期货这边费率、保证金、开仓手数变一档，股票这边报撤监控和要不要先报告变一档。开关位置错了，同一段行情算出来的成本和可行动作全不一样，所以日历本身也是数据，要像行情一样做版本管理。</span>缺失历史阈值时，用定性分段（「监控强化期」）做稳健性，而不是发明具体笔数。论文应声明：结论成立于哪些制度区间。</p><p>产品层：公募、私募、QFII 的报告路径不同，容量与合规成本不同。同一因子在三类产品上的可实现换手应分列。</p>',12)),(A(),B(l,null,{default:e(()=>[o(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%9B%9E%E6%B5%8B%E6%8E%A8%E8%BF%9B%E5%88%B0%E6%9F%90%E4%BA%A4%E6%98%93%E6%97%A5%22%5D%20--%3E%20LK%5B%22%E6%9F%A5%E5%88%B6%E5%BA%A6%E6%97%A5%E5%8E%86%3A%20%E8%AF%A5%E6%97%A5%E5%B1%9E%E4%BA%8E%E5%93%AA%E4%B8%AA%20regime%22%5D%0A%20%20LK%20--%3E%20A%5B%22%E6%9C%9F%E8%B4%A7%E5%BC%80%E5%85%B3%3A%20%E8%B4%B9%E7%8E%87%2F%E4%BF%9D%E8%AF%81%E9%87%91%2F%E6%97%A5%E5%86%85%E5%BC%80%E4%BB%93%E4%B8%8A%E9%99%90%22%5D%0A%20%20LK%20--%3E%20B%5B%22%E8%82%A1%E7%A5%A8%E5%BC%80%E5%85%B3%3A%20%E5%BC%82%E5%B8%B8%E6%8A%A5%E6%92%A4%E7%9B%91%E6%8E%A7%E5%8F%A3%E5%BE%84%22%5D%0A%20%20LK%20--%3E%20C%5B%22%E6%8A%A5%E5%91%8A%E5%BC%80%E5%85%B3%3A%20%E6%98%AF%E5%90%A6%E5%85%88%E6%8A%A5%E5%91%8A%E5%90%8E%E4%BA%A4%E6%98%93%22%5D%0A%20%20LK%20--%3E%20E%5B%22%E8%9E%8D%E5%88%B8%E5%BC%80%E5%85%B3%3A%20%E8%9E%8D%E5%88%B8%E7%AE%A1%E9%81%93%E6%98%AF%E5%90%A6%E5%8F%AF%E7%94%A8%22%5D%0A%20%20A%20--%3E%20FS%5B%22%E5%90%88%E6%88%90%E5%BD%93%E6%9C%9F%E5%90%88%E6%B3%95%E5%8A%A8%E4%BD%9C%E9%9B%86%22%5D%0A%20%20B%20--%3E%20FS%0A%20%20C%20--%3E%20FS%0A%20%20E%20--%3E%20FS%0A%20%20FS%20--%3E%20EV%5B%22%E5%8F%AA%E5%9C%A8%E5%8A%A8%E4%BD%9C%E9%9B%86%E5%86%85%E6%92%AE%E5%90%88%E5%B9%B6%E8%AE%A1%E6%88%90%E6%9C%AC%22%5D%0A%20%20EV%20--%3E%20RID%5B%22%E5%86%99%E5%85%A5%20reg_regime_id%20%E4%BE%9B%E5%88%86%E6%AE%B5%E7%BB%9F%E8%AE%A1%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=n('<h3 id="与故障、熔断的区别" tabindex="-1">与故障、熔断的区别 <a class="header-anchor" href="#与故障、熔断的区别" aria-label="Permalink to &quot;与故障、熔断的区别&quot;">​</a></h3><p>2016 年熔断是价格限制的短暂实验，对象是指数跌幅，不是程序化定义。本课不把熔断细则重写一遍，只强调：制度实验会进入收益方差，须分段。技术故障见交易所故障课，原因码不同。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>监管改变报撤与空头的影子价格，从而改变最优市场结构参与方式：从高频做市转向低频截面，或从个股空头转向期货中性。这是均衡迁移。<span class="marginnote">均衡迁移可以类比河道改道：上游修了坝（监管收紧报撤、限制融券），水不会消失，只会改道——容量从高频做市流去低频选股，从个股空头流去期货对冲。所以某因子样本外突然衰减时，先查河道有没有改（制度变了），再怀疑策略拥挤。</span>样本外衰减若发生在细则施行附近，应先检验制度，再检验拥挤。研究日志的制度登记就是为这一检验准备分母。</p><p>国际对照：Reg NMS、MiFID 不是 A 股的替代文本，只能当「高频监管工具箱」的对照，阈值与报告义务不可横搬。</p>',5)),(A(),B(l,null,{default:e(()=>[o(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y2015%5B%222015%20%E6%9C%9F%E8%B4%A7%E4%B8%8E%E5%BC%82%E5%B8%B8%E4%BA%A4%E6%98%93%22%5D%20--%3E%20Y2019%5B%22%E7%9B%91%E6%8E%A7%E4%B8%8E%E6%8A%A5%E5%91%8A%E5%AE%9E%E8%B7%B5%22%5D%0A%20%20Y2019%20--%3E%20Y2024%5B%22%E7%AE%A1%E7%90%86%E8%A7%84%E5%AE%9A%20%E5%85%88%E6%8A%A5%E5%91%8A%22%5D%0A%20%20Y2024%20--%3E%20Y2025%5B%22%E5%AE%9E%E6%96%BD%E7%BB%86%E5%88%99%20%E5%9B%9B%E7%B1%BB%E5%BC%82%E5%B8%B8%22%5D%0A%20%20Y2025%20--%3E%20Feas%5B%22%E5%BD%93%E6%97%B6%E5%90%88%E6%B3%95%E5%8A%A8%E4%BD%9C%E9%9B%86%22%5D%0A%20%20Feas%20--%3E%20BT%5B%22%E5%88%86%E6%AE%B5%E5%9B%9E%E6%B5%8B%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=a("h2",{id:"边界",tabindex:"-1"},[t("边界 "),a("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),E[5]||(E[5]=a("p",null,"不提供规避报告、分拆产品、或把报撤维持在监控指标「刚好以下」的操作指南。以公开规定为准。本课是制度史与回测分段，不是法律意见。",-1)),E[6]||(E[6]=a("h2",{id:"小结",tabindex:"-1"},[t("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),E[7]||(E[7]=a("ul",null,[a("li",null,"量化可行集随 2015→2025 的规则叠加而变；禁止现行细则回填全样本。"),a("li",null,"监管冲击通过报撤成本、空头工具与公平接入改变容量。"),a("li",null,"产品类型（公募/私募/北向）报告路径不同，应分列实现。"),a("li",null,"出处：证监会 2024 年《管理规定》；交易所 2025 年实施细则；2015 年以来期货与异常交易公开措施。")],-1))])}const q=i(p,[["render",u]]);export{g as __pageData,q as default};
